12	
13	/**
14	 * The complete action vocabulary of `can()`. Every authorization decision in
15	 * Taskflow names one of these — there is no free-form string permission.
16	 */
17	export type PermissionAction =
18	  | "org:read"
19	  | "org:update"
20	  | "org:delete"
21	  | "org:manage_billing"
22	  | "org:manage_flags"
23	  | "member:read"
24	  | "member:invite"
25	  | "member:update_role"
26	  | "member:remove"
27	  | "project:create"
28	  | "project:read"
29	  | "project:update"
30	  | "project:archive"
31	  | "project:delete"
32	  | "issue:create"
33	  | "issue:read"
34	  | "issue:update"
35	  | "issue:assign"
36	  | "issue:archive"
37	  | "issue:delete"
38	  | "comment:create"
39	  | "comment:read"
40	  | "comment:update"
41	  | "comment:delete"
