/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug. The workspace stays inert
 * and restorable until the retention sweep purges it.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  assertNotArchived("Organization", input.orgId, org);

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  const deleted = await orgRepo.archiveOrg(input.orgId);

  await emit("organization.deleted", {
    ...actorEnvelope(actor),
    slug: deleted.slug,
  });

  return deleted;
}

/**
 * Brings a deleted workspace back while its retention window is open. A deleted
 * workspace yields no `Actor` (sign-in and membership lookups skip it), so the
 * caller is identified by user id and the actor is rebuilt from the membership.
 * Restoring a live workspace is a no-op that publishes nothing.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) throw new NotFoundError("Organization", orgId);

  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Organization", orgId);
  }

  if (org.archivedAt !== null && retentionClosed(org.archivedAt, new Date())) {
    throw new NotFoundError("Organization", orgId);
  }

  assertCan(
    { userId, orgId, role: member.role },
    "org:restore",
    orgResource(orgId),
  );

  if (org.archivedAt === null) return org;

  const restored = await orgRepo.restoreOrg(orgId);

  await emit("organization.restored", {
    ...envelope(orgId, userId),
    slug: restored.slug,
  });

  return restored;
}

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** True once `DELETED_WORKSPACE_RETENTION_DAYS` have passed since deletion. */
function retentionClosed(deletedAt: IsoTimestamp, now: Date): boolean {
  const windowMs = DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY;
  return now.getTime() - Date.parse(deletedAt) >= windowMs;
}

