afterAll(() => {
  for (const off of offs) off();
  unregisterEventHandlers();
  vi.useRealTimers();
  cleanup();
});

describe("workspace deletion lifecycle", () => {
  const orgId = () => tenant.org.id as OrgId;

  it("deletes, publishes, audits, and rejects a second delete", async () => {
    await deleteOrganization(tenant.actors.owner, { orgId: orgId(), confirmSlug: "scratchws-inc" as never }).catch(() => undefined);
    const org = await deleteOrganization(tenant.actors.owner, {
      orgId: orgId(),
      confirmSlug: tenant.org.slug,
    });
    expect(org.archivedAt).not.toBeNull();
    expect(seen).toContain("deleted:scratchws");
    await expect(
      deleteOrganization(tenant.actors.owner, { orgId: orgId(), confirmSlug: tenant.org.slug }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const page = await listActivity(tenant.actors.owner, {
      orgId: orgId(),
      action: ["organization.deleted"],
      limit: 10,
      cursor: null,
    });
    expect(page.items.map((e) => [e.action, e.subjectKind, e.subjectId, e.actorId])).toEqual([
      ["organization.deleted", "organization", orgId(), tenant.userIds.owner],
    ]);
  });

  it("is inert while deleted", async () => {
    expect(await resolveOrgBySlug("scratchws")).toBeNull();
    expect((await listOrganizationsForUser(tenant.userIds.member)).map((o) => o.id)).not.toContain(orgId());
    const created = await notify(orgId(), "issue_assigned", [tenant.userIds.member], {
      title: "t", body: "b", href: "/x", actorId: null,
    });
    expect(created).toEqual([]);
  });

  it("refuses restore by a non-owner member, and by a non-member", async () => {
    await expect(restoreOrganization(tenant.userIds.member, orgId())).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(restoreOrganization(tenant.userIds.member, orgId())).rejects.toThrow();
    const outsider = "NOT-A-MEMBER-USER-ID" as never;
    await expect(restoreOrganization(outsider, orgId())).rejects.toBeInstanceOf(NotFoundError);
  });

  it("restores for the owner, publishes, audits, and is idempotent", async () => {
    const restored = await restoreOrganization(tenant.userIds.owner, orgId());
    expect(restored.archivedAt).toBeNull();
    expect(seen).toContain("restored:scratchws");
    expect(await resolveOrgBySlug("scratchws")).not.toBeNull();

    const before = seen.length;
    const again = await restoreOrganization(tenant.userIds.owner, orgId());
    expect(again.archivedAt).toBeNull();
    expect(seen.length).toBe(before);

    const created = await notify(orgId(), "issue_assigned", [tenant.userIds.member], {
      title: "t", body: "b", href: "/x", actorId: null,
    });
    expect(created.length).toBe(1);
  });

  it("keeps a deleted workspace inside its window and purges it after", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    const t0 = new Date("2030-01-01T00:00:00.000Z");
    vi.setSystemTime(t0);
    await deleteOrganization(tenant.actors.owner, { orgId: orgId(), confirmSlug: tenant.org.slug });

    vi.setSystemTime(new Date(t0.getTime() + (DELETED_WORKSPACE_RETENTION_DAYS - 1) * DAY));
    await runCleanupArchivedJob(new Date());
    expect(await orgRepo.findOrgById(orgId())).not.toBeNull();
    await expect(restoreOrganization(tenant.userIds.owner, orgId())).resolves.toMatchObject({ archivedAt: null });

    await deleteOrganization(tenant.actors.owner, { orgId: orgId(), confirmSlug: tenant.org.slug });
    vi.setSystemTime(new Date(t0.getTime() + 100 * DAY));
    await expect(restoreOrganization(tenant.userIds.owner, orgId())).rejects.toBeInstanceOf(NotFoundError);

    const result = await runCleanupArchivedJob(new Date());
    expect(result.failed).toBe(0);
    expect(await orgRepo.findOrgById(orgId())).toBeNull();
    await expect(restoreOrganization(tenant.userIds.owner, orgId())).rejects.toBeInstanceOf(NotFoundError);

    const reborn = await createOrganization(tenant.userIds.owner, { name: "Again", slug: "scratchws", plan: "free" });
    expect(reborn.slug).toBe("scratchws");
    vi.useRealTimers();
  });
});
